import{_ as t,c as i,o,al as a}from"./chunks/framework.D8UyiDWg.js";const _=JSON.parse('{"title":"Test MC_07 - VIO (Visual-Inertial Odometry)","description":"","frontmatter":{},"headers":[],"relativePath":"en/test_cards/mc_07_vio.md","filePath":"en/test_cards/mc_07_vio.md"}'),l={name:"en/test_cards/mc_07_vio.md"};function r(n,e,s,d,h,c){return o(),i("div",null,e[0]||(e[0]=[a('<h1 id="test-mc-07-vio-visual-inertial-odometry" tabindex="-1">Test MC_07 - VIO (Visual-Inertial Odometry) <a class="header-anchor" href="#test-mc-07-vio-visual-inertial-odometry" aria-label="Permalink to &quot;Test MC_07 - VIO (Visual-Inertial Odometry)&quot;">​</a></h1><h2 id="objective" tabindex="-1">Objective <a class="header-anchor" href="#objective" aria-label="Permalink to &quot;Objective&quot;">​</a></h2><p>To test that external vision (VIO) works as expected</p><h2 id="preflight" tabindex="-1">Preflight <a class="header-anchor" href="#preflight" aria-label="Permalink to &quot;Preflight&quot;">​</a></h2><p>Disconnect all GPS / compasses and ensure vehicle is using VIO for navigation</p><p>Ensure that the drone can go into Altitude / Position flight mode while still on the ground</p><p>Ensure there are no other sources of positioning besides VIO:</p><ul><li><a href="./../advanced_config/parameter_reference.html#EKF2_OF_CTRL">EKF2_OF_CTRL</a>: <code>0</code></li><li><a href="./../advanced_config/parameter_reference.html#EKF2_GPS_CTRL">EKF2_GPS_CTRL</a>: <code>0</code></li><li><a href="./../advanced_config/parameter_reference.html#EKF2_EV_CTRL">EKF2_EV_CTRL</a>: <code>15</code></li><li><a href="./../advanced_config/parameter_reference.html#SYS_HAS_MAG">SYS_HAS_MAG</a>: <code>0</code></li></ul><h2 id="flight-tests" tabindex="-1">Flight Tests <a class="header-anchor" href="#flight-tests" aria-label="Permalink to &quot;Flight Tests&quot;">​</a></h2><p>❏ Altitude flight mode</p><p>    ❏ Vertical position should hold current value with stick centered</p><p>    ❏ Pitch/Roll/Yaw response 1:1</p><p>    ❏ Throttle response set to climb/descent rate</p><p>❏ Position flight mode</p><p>    ❏ Horizontal position should hold current value with stick centered</p><p>    ❏ Vertical position should hold current value with stick centered</p><p>    ❏ Throttle response set to climb/descent rate</p><p>    ❏ Pitch/Roll/Yaw response set to pitch/roll/yaw rates</p><h2 id="landing" tabindex="-1">Landing <a class="header-anchor" href="#landing" aria-label="Permalink to &quot;Landing&quot;">​</a></h2><p>❏ Land in either Position or Altitude mode with the throttle below 40%</p><p>❏ Upon touching ground, copter should disarm automatically within 2 seconds (default: see <a href="./../advanced_config/parameter_reference.html#COM_DISARM_LAND">COM_DISARM_LAND</a>)</p><h2 id="expected-results" tabindex="-1">Expected Results <a class="header-anchor" href="#expected-results" aria-label="Permalink to &quot;Expected Results&quot;">​</a></h2><ul><li>Take-off should be smooth as throttle is raised</li><li>Drone should hold altitude in Altitude Flight mode without wandering</li><li>Drone should hold position within 1 meter in Position Flight mode without pilot moving sticks</li><li>No oscillations should present in any of the above flight modes</li><li>Upon landing, copter should not bounce on the ground</li></ul>',23)]))}const u=t(l,[["render",r]]);export{_ as __pageData,u as default};
